// Selected TUGA-style coefficient tiles, generated by the exact GUGA oracle.
// The cache contains <CSF|E|CSF> / <CSF|e|CSF>, never integral-weighted H.
class SymbolicTiles {
    struct Slot {
        std::unique_ptr<char[]> key;
        std::unique_ptr<double[]> coefficients;
        size_t hash=0, key_size=0, count=0, recent=0;
        size_t bytes() const { return key_size+count*sizeof(double); }
    };
    size_t maximum_, bytes_=0, clock_=0, cursor_=0;
    std::vector<Slot> slots_;
    size_t hits_=0, misses_=0, bypass_=0, evictions_=0, generated_=0, contracted_=0;
    size_t peak_=0;
    size_t scratch_peak_=0;

    void erase(size_t i) {
        auto &s=slots_[i];
        if (!s.key) return;
        bytes_-=s.bytes();s=Slot{};++evictions_;
    }
public:
    explicit SymbolicTiles(size_t maximum) : maximum_(maximum) {
        // Fixed two-way directory; requested allocation sizes, including the
        // directory, are charged. No allocator-specific hash nodes are hidden.
        size_t count=maximum/1024;
        if (!count && maximum>=sizeof(Slot)) count=1;
        if (count>1) count-=count%2;
        slots_.resize(count);bytes_=slots_.capacity()*sizeof(Slot);peak_=bytes_;
    }
    std::array<size_t,6> counters() const {
        return {hits_,misses_,bypass_,evictions_,generated_,contracted_};
    }
    size_t bytes() const { return bytes_; }
    size_t peak() const { return peak_; }
    size_t scratch_peak() const { return scratch_peak_; }
    size_t entries() const {
        size_t n=0;for (const auto &s:slots_) n+=bool(s.key);return n;
    }
    size_t coefficients() const {
        size_t n=0;for (const auto &s:slots_) n+=s.count;return n;
    }

    bool batch(const Config &bra_cfg,const Config &ket_cfg,const std::vector<Path> &paths,
               IndexView rows,IndexView cols,const Connection &c,const GugaLeanPlan &plan,
               const std::vector<std::uint64_t> &down,GugaMemo &memo,bool accelerated,
               size_t maximum_rectangle,bool same,GugaBatchScratch &scratch) {
        if (slots_.empty() || bra_cfg.size()>64 || rows.empty() || cols.empty() ||
            rows.size()>maximum_rectangle/cols.size() || c.generators.empty()) {
            ++bypass_;return false;
        }
        const size_t rectangle=rows.size()*cols.size(), nt=c.generators.size();
        // Same-configuration traversal consumes only the strict lower triangle
        // in the local (increasing global-index) lists. Cache exactly those
        // entries: no symmetry assumption about a generator is needed.
        const size_t tile_size=same ? rows.size()*(rows.size()-1)/2 : rectangle;
        if (!tile_size || nt>(maximum_-slots_.capacity()*sizeof(Slot))/sizeof(double)/tile_size) {
            ++bypass_;return false;
        }
        // Keep every singly occupied spectator and every operator endpoint.
        // Remove only common empty/doubly occupied non-endpoints. Full selected
        // step sequences retain all entering spins and orthogonality tests.
        std::array<int,64> mapped{};mapped.fill(-1);int kept=0;
        std::array<bool,64> keep{};
        for (size_t p=0;p<bra_cfg.size();++p)
            keep[p]=bra_cfg[p]==1 || ket_cfg[p]==1 || bra_cfg[p]!=ket_cfg[p];
        for (const auto &t:c.generators) {
            keep[t.p]=keep[t.q]=true;
            if (t.two_body) keep[t.r]=keep[t.s]=true;
        }
        for (size_t p=0;p<bra_cfg.size();++p) if (keep[p]) mapped[p]=kept++;
        std::string key;
        auto integer=[&](size_t x) { key.append(reinterpret_cast<const char *>(&x),sizeof(x)); };
        integer(rows.size());integer(cols.size());integer(nt);integer(kept);integer(same);
        for (const auto &t:c.generators) {
            integer(t.two_body);integer(mapped[t.p]);integer(mapped[t.q]);
            if (t.two_body) { integer(mapped[t.r]);integer(mapped[t.s]); }
        }
        for (auto indices:{rows,cols}) for (size_t i:indices)
            for (size_t p=0;p<bra_cfg.size();++p) if (keep[p]) key.push_back(paths[i].label[p]);
        size_t count=tile_size*nt;
        if (key.size()>maximum_-slots_.capacity()*sizeof(Slot)-count*sizeof(double)) { ++bypass_;return false; }
        size_t payload=key.size()+count*sizeof(double);
        size_t hash=std::hash<std::string>{}(key), ways=slots_.size()>1 ? 2 : 1;
        size_t base=ways*(hash%(slots_.size()/ways)), chosen=base;
        bool hit=false;
        for (size_t w=0;w<ways;++w) {
            const auto &s=slots_[base+w];
            if (s.key && s.hash==hash && s.key_size==key.size() &&
                std::equal(key.begin(),key.end(),s.key.get())) { chosen=base+w;hit=true;break; }
            if (!s.key || s.recent<slots_[chosen].recent) chosen=base+w;
        }
        // The common-closed phase can differ for each generator. The external
        // CG convention phase can differ for each selected bra/ket path.
        std::vector<int> parity(nt,1);
        scratch_peak_=std::max(scratch_peak_,key.capacity()+1+parity.capacity()*sizeof(int)+sizeof(GugaTerm)+sizeof(GugaLeanTerm));
        for (size_t a=0;a<nt;++a) {
            const auto &t=c.generators[a];
            for (size_t p=0;p<bra_cfg.size();++p) if (!keep[p] && ket_cfg[p]==2) {
                int active=std::min(t.p,t.q)<int(p) && int(p)<std::max(t.p,t.q);
                if (t.two_body) active+=std::min(t.r,t.s)<int(p) && int(p)<std::max(t.r,t.s);
                if (active%2) parity[a]=-parity[a];
            }
        }
        if (hit) ++hits_;
        else {
            ++misses_;erase(chosen);
            while (payload>maximum_-bytes_) {
                erase(cursor_);cursor_=(cursor_+1)%slots_.size();
            }
            // Publish only a complete tile; exceptions leave a valid cache.
            Slot fresh;
            fresh.key=std::make_unique<char[]>(key.size());
            std::copy(key.begin(),key.end(),fresh.key.get());
            fresh.coefficients=std::make_unique<double[]>(count);
            fresh.key_size=key.size();fresh.count=count;fresh.hash=hash;
            Connection unit;unit.guga=true;unit.generators.resize(1);
            GugaLeanPlan unit_plan(1);
            for (size_t a=0;a<nt;++a) {
                unit.generators[0]=c.generators[a];unit.generators[0].coefficient=1.;
                unit_plan[0]=plan[a];
                for (size_t r=0;r<rows.size();++r) for (size_t s=0;s<(same ? r : cols.size());++s) {
                    size_t i=rows[r],j=cols[s];
                    double v=memo.small_element(paths[i],paths[j],unit,unit_plan,down[i],down[j],accelerated);
                    fresh.coefficients[a*tile_size+(same ? r*(r-1)/2 : r*cols.size())+s]=v*paths[i].phase*paths[j].phase*parity[a];
                }
            }
            generated_+=count;bytes_+=payload;peak_=std::max(peak_,bytes_);slots_[chosen]=std::move(fresh);
        }
        auto &slot=slots_[chosen];slot.recent=++clock_;
        auto &out=scratch.values;out.assign(rectangle,0.);
        for (size_t a=0;a<nt;++a) {
            double weight=c.generators[a].coefficient*parity[a];
            const double *values=slot.coefficients.get()+a*tile_size;
            if (same) {
                for (size_t r=0;r<rows.size();++r) for (size_t s=0;s<r;++s)
                    out[r*cols.size()+s]+=weight*values[r*(r-1)/2+s];
            } else for (size_t p=0;p<rectangle;++p) out[p]+=weight*values[p];
        }
        for (size_t r=0;r<rows.size();++r) for (size_t s=0;s<cols.size();++s)
            out[r*cols.size()+s]*=paths[rows[r]].phase*paths[cols[s]].phase;
        contracted_+=count;
        return true;
    }
};
